flowchart TD
    CPU[CPU issues load] --> L1{L1 hit? 0.5ns}
    L1 -->|yes| DONE1[return]
    L1 -->|no| L2{L2 hit? 7ns}
    L2 -->|yes| DONE2[return]
    L2 -->|no| L3{L3 hit? 20ns}
    L3 -->|yes| DONE3[return]
    L3 -->|no| DRAM{DRAM hit? 100ns}
    DRAM -->|yes| DONE4[return]
    DRAM -->|no| SSD{SSD or remote? 150us to 500us}
    SSD -->|yes| DONE5[return after stall]
    SSD -->|no| NET[Cross-region fetch 100ms+]

// Size from working set, not from DB size.
// hotBytes = requestsPerSec * workingSetWindowSec * avgObjectBytes * skewFactor
long hotBytes = 20_000L * 300L * 2_048L; // 20k rps, 5-min reuse window ~ 12 GB
// Allow headroom: target <= 70% occupancy to avoid LRU cliff + fragmentation.
long cacheBytes = (long) (hotBytes / 0.70);
// Enforce admission: do not let one-shot keys evict the hot set.
// TinyLFU / sampled LRU beats naive LRU when scan traffic exists.
Cache<String, byte[]> cache = Caffeine.newBuilder()
    .maximumWeight(cacheBytes)
    .weigher((String k, byte[] v) -> v.length)
    .expireAfterWrite(Duration.ofMinutes(5))
    .recordStats() // alert on hitRate, evictionCount, not just size
    .build();
